proved AND profile IS NULL;
UPDATE companies SET description='All-Type Welding and Fabrication, Inc. was founded in 1987 and operates a 34,000-square-foot facility in Glenwillow, Ohio, a suburb of Cleveland. The company has provided comprehensive precision metal fabrication and welding services for over three decades.

The shop specializes in precision metal fabrication, laser cutting, welding, finishing, powder coating, and inspection. Its capabilities include in-house engineering for design improvements, rapid prototyping with turnaround ranging from same-day to five days, and ISO 9001:2015 certified inspection processes. The facility houses laser cutting machines that accommodate sheets up to 60 by 120 inches and one inch thick, along with MIG and spot welding equipment, a laser etching system, and a 3D printer for prototyping.

All-Type serves original equipment manufacturers across industries including foodservice equipment, aerospace, pharmaceutical, material handling, military and defense, transportation, power distribution, fuel cell, and construction equipment. Notable projects include work for an Ohio brewery and a construction equipment supplier.

The company differentiates itself through its team of experts who began their careers as skilled welders, its ability to work with difficult metals such as Inconel and various stainless steels and aluminums, and a problem-solving approach that involves engineering collaboration during the design phase.', certifications=ARRAY['ISO 9001:2015','MIL-STD-1595A','MIL-STD-2219A','AWS D1.1','AWS D1.2','AWS D1.6','AWS D17.1']::text[], profile='{"capabilities": ["Precision metal fabrication", "Laser cutting (up to 60\" x 120\", 1\" thick)", "MIG welding", "Spot welding", "Laser etching", "Powder coating", "Engineering design services", "Rapid prototyping (3D printing)", "ISO 9001:2015 inspection", "Sheet metal fabrication", "Finishing services"], "industries": ["Foodservice equipment", "Aerospace", "Pharmaceutical", "Material handling", "Military & defense", "Transportation", "Power distribution", "Fuel cell", "Construction equipment", "Brewery", "Original equipment manufacturers (OEMs)"], "materials": ["Stainless steel", "Aluminum", "Carbon steel", "Inconel", "Copper", "Brass", "Bronze", "Superalloys"], "equipment": ["Fronius TPS 320i MIG welding machine", "TECNA 20 KVA Rocker Arm Spot Welder", "Kaeser AS20 compressor", "Trumpf TruMark Station 300 laser etching machine", "3D printer"], "volume": "", "lead_time": "Same-day to five days for prototyping depending on complexity", "tolerances": "", "built_on": ["In-house engineering for design improvements and cost reduction", "Rapid prototyping with same-day to five-day turnaround", "ISO 9001:2015 certified inspection with experienced inspectors", "Expertise in welding and fabricating difficult metals (Inconel, stainless steels, aluminums)", "34,000 sq ft facility with integrated laser cutting, machining, and finishing equipment"], "facts_used": ["Founded in 1987 -> /about-us", "34,000-square-foot facility in Glenwillow, Ohio -> /about-us", "ISO 9001:2015 certified -> /about-us, /", "Laser cutting up to 60x120 inches, 1 inch thi