UPDATE companies SET description='Anderson Woodworks is a one-person woodworking shop based in Yelm, Washington, founded by Brian Anderson. An Olympia-area native, Anderson spent roughly twelve years in custom home building before opening his own shop, applying that experience to furniture and cabinetry that must live in real houses.

The shop produces custom furniture, cabinetry, and built-ins entirely by hand using traditional joinery. Offerings include dining tables, desks, consoles, kitchen and vanity cabinets, library systems, and one-of-a-kind collector pieces featuring hand-cut dovetails, mortise-and-tenon joints, and marquetry inlay. All work is built in Anderson’s Yelm shop; he handles design, fabrication, and delivery, while installation is left to the client’s contractor.

Anderson serves homeowners, collectors, and designers throughout the South Sound region—Olympia, Lacey, Tumwater, Tacoma, Gig Harbor, and Thurston and Pierce Counties. The business also provides furniture-led interior design consultations, including space planning, material selection, and full-room design packages that integrate custom pieces.

Anderson emphasizes that his joinery methods—hand-cut dovetails and mortise-and-tenon—are the same techniques that have kept furniture standing for centuries. He positions the shop as an alternative to mass-produced, fastener-dependent furniture, offering direct collaboration with the maker and a design philosophy rooted in longevity rather than trends.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture making", "Cabinetry and built-ins", "Collector pieces (one-of-a-kind)", "Hand-cut dovetail joinery", "Mortise-and-tenon joinery", "Marquetry inlay", "Furniture-led interior design consultation", "Space planning and layout", "Material and finish selection", "Design and fabrication", "On-site estimates"], "industries": ["Residential furniture", "Custom cabinetry", "Interior design", "High-end woodworking"], "materials": ["Hardwoods", "Locally sourced materials"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Location: Yelm, Washington -> db", "Founder: Brian Anderson -> /", "Background: 12 years custom home building -> /", "Processes: hand-cut dovetails, mortise-and-tenon, marquetry -> /", "Products: custom furniture, cabinetry, built-ins, collector pieces -> /", "Service area: South Sound region (Olympia, Lacey, Tumwater, Tacoma, Gig Harbor, Thurston and Pierce Counties) -> /", "Collector pieces ship beyond Washington -> /", "Furniture-led interior design consultation offered -> /about-us", "Studio Line and Collector Line product tiers -> /about-us", "Single-maker operation -> /", "Free on-site estimates -> /", "Materials: carefully selected hardwoods, local materials -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Custom furniture, cabinetry, and built-ins, handcrafted one piece at a time with traditional joinery in Yelm, Washington.", "founded_year": "", "employee_count": "1", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "